function uiText(text,language=uiLanguage){const row=UI_TEXT[text];return language==='vi'||!row?text:row[language==='zh'?1:0];}
const uiOriginal=new WeakMap();
const UI_SKIP='input,textarea,pre,code,script,style,[data-i18n-skip],.voice-label strong,.speaker-row button:first-of-type,.file-info,.project-open strong,#download-list .download-select-row strong,.seq-clip,.seq-media-name,.seq-clip-name,.voice-select option:not([value=""]),[data-tts="voice"] option:not([value=""]),#seq-project option:not([value=""]),#caption-preview,#reading-preview';
