// UI icons/step numbers belong to the layout, not to translation keys.
function uiLabel(text,language=uiLanguage){
 if(language==='vi')return text;
 const key=text.trim();if(UI_TEXT[key])return text.replace(key,uiText(key,language));
 const decorated=key.match(/^([\s\d.＋+↓↑↥↻↶↷↩←→▶◷●☁✧✎✦◆♬☺≈ⅡAᵃ📂📁▧⚙✓×]+)?(.+?)([\s×✕]+)?$/u);
 if(decorated&&UI_TEXT[decorated[2]])return text.replace(key,(decorated[1]||'')+uiText(decorated[2],language)+(decorated[3]||''));
 const rate=key.match(/^(\d+(?:\.\d+)?×\s*·\s*)(Chậm|Nhanh)$/);
 if(rate)return text.replace(key,rate[1]+uiText(rate[2],language));
 // Only known, anchored UI templates; never translate arbitrary payloads.
 const batch=key.match(/^(\d+) cue (sẽ áp dụng|đã cập nhật) · (\d+) cue khóa bỏ qua$/);if(batch)return text.replace(key,language==='zh'?`${batch[1]} 条字幕${batch[2]==='sẽ áp dụng'?'将应用':'已更新'} · 跳过 ${batch[3]} 条锁定字幕`:`${batch[1]} cues ${batch[2]==='sẽ áp dụng'?'to apply':'updated'} · ${batch[3]} locked cues skipped`);
 const selected=key.match(/^Đang chọn: (.*)$/);if(selected)return text.replace(key,(language==='zh'?'当前声音：':'Selected: ')+selected[1]);
 const count=key.match(/^([\d.,]+) ký tự(?: · ([\d.,]+) từ)?$/);if(count)return text.replace(key,language==='zh'?`${count[1]} 字符${count[2]?' · '+count[2]+' 词':''}`:`${count[1]} characters${count[2]?' · '+count[2]+' words':''}`);
 const estimate=key.match(/^Ước tính audio: ([\d.–]+) giây( · đã tính luật đọc)?$/);if(estimate)return text.replace(key,language==='zh'?`预计音频：${estimate[1]} 秒${estimate[2]?' · 已计入朗读规则':''}`:`Estimated audio: ${estimate[1]}s${estimate[2]?' · reading rules included':''}`);
 const picked=key.match(/^(\d+) (đã chọn|file đã chọn)$/);if(picked)return text.replace(key,language==='zh'?`${picked[1]} 已选`:`${picked[1]} selected`);
 const clips=key.match(/^(\d+) clip được chọn$/);if(clips)return text.replace(key,language==='zh'?`${clips[1]} 个片段已选`:`${clips[1]} clips selected`);
 const projectStats=key.match(/^(\d+) câu · (\d+) đã tạo$/);if(projectStats)return text.replace(key,language==='zh'?`${projectStats[1]} 句 · 已生成 ${projectStats[2]} 句`:`${projectStats[1]} cues · ${projectStats[2]} generated`);
 const sourceSize=key.match(/^([\d?]+×[\d?]+) · nguồn ([\d?]+×[\d?]+)$/);if(sourceSize)return text.replace(key,`${sourceSize[1]} · ${language==='zh'?'来源':'source'} ${sourceSize[2]}`);
 const license=key.match(/^(.+) Mã máy: (.+)$/);if(license&&UI_TEXT[license[1]])return text.replace(key,uiText(license[1],language)+(language==='zh'?' 机器码：':' Machine ID: ')+license[2]);
 const compound=key.match(/^(Gỡ bỏ|Giọng \/ ngôn ngữ|Nghe thử|Giọng \/ diễn xuất|Đang dùng) · (.+)$/);
 if(compound)return text.replace(key,uiText(compound[1],language)+' · '+uiText(compound[2],language));
 const remove=key.match(/^Bỏ (.+)$/);if(remove&&UI_TEXT[remove[1]])return text.replace(key,uiText('Bỏ',language)+' '+uiText(remove[1],language));
 const install=key.match(/^Tải qua Internet và cài vào: (.+)\?$/);if(install)return language==='zh'?`通过网络下载并安装到：${install[1]}？`:`Download over the Internet and install into: ${install[1]}?`;
 const editDownload=key.match(/^Tạo một dự án Biên tập mới với (\d+) file nối tiếp\? Dự án cũ được giữ\.$/);if(editDownload)return language==='zh'?`用 ${editDownload[1]} 个连续文件新建编辑项目？旧项目保留。`:`Create an Editor project with ${editDownload[1]} sequential files? Existing projects are kept.`;
 const dubDownload=key.match(/^Tạo (\d+) dự án Lồng tiếng, một dự án mỗi video\? Mở dự án đầu tiên; các dự án khác nằm trong danh sách\.$/);if(dubDownload)return language==='zh'?`新建 ${dubDownload[1]} 个配音项目，每视频一个？打开首项目，其余在列表中。`:`Create ${dubDownload[1]} Dubbing projects, one per video? Opens the first; others appear in the list.`;
 const location=key.match(/^Lưu tại: (.+)$/);if(location)return text.replace(key,(language==='zh'?'保存位置：':'Saved in: ')+location[1]);
 const speed=key.match(/^(Tốc độ thực tế|Ước tính) ([\d.]+×), khung ([\d.]+s)( · audio cũ)?$/);if(speed)return text.replace(key,language==='zh'?`${speed[1]==='Ước tính'?'预计':'实际语速'} ${speed[2]}，时段 ${speed[3]}${speed[4]?' · 旧音频':''}`:`${speed[1]==='Ước tính'?'Estimated':'Actual speed'} ${speed[2]}, slot ${speed[3]}${speed[4]?' · stale audio':''}`);
 const fluent=key.match(/^(.+) · (Fluent (?:3D|Flat))$/);if(fluent&&UI_TEXT[fluent[1]])return text.replace(key,uiText(fluent[1],language)+' · '+fluent[2]);
 // Voice metadata is UI; voice names (strong) remain protected above.
 if(key.includes(' · ')){const parts=key.split(' · ');if(parts.every(p=>UI_TEXT[p]||/^(?:[\d.]+ kHz|VieNeu)$/.test(p)))return text.replace(key,parts.map((p,i)=>uiText(i>0&&p==='Nam'?'Nam Bộ':p,language)).join(' · '));}
 return text;
}
function uiTranslateDOM(root=document.body){
 const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);
 while(walker.nextNode()){
  const node=walker.currentNode,parent=node.parentElement;
  if(!parent)continue;
  const previous=uiOriginal.get(node);const original=previous&&node.nodeValue===previous.display?previous.original:node.nodeValue;
  // Empty file status is UI; actual file names remain protected, even when
  // they happen to equal a translated menu label.
  const emptyFileStatus=parent.closest('.file-info')&&['Chưa chọn tài liệu','Chưa chọn mẫu giọng'].includes(original.trim());
  if(parent.closest(UI_SKIP)&&!emptyFileStatus)continue;
  // Narrow templates to UI nodes; exact catalog labels also cover static spans.
  if(!emptyFileStatus&&!parent.closest('button,label,summary,option,a,.hint,.notice,.card-heading,h1,h2,h3,.tabs,.topbar,.local-badge,.settings-page,.page-heading,.editor-tools,.editor-bottom,.range-labels,.player-info,.empty,.voice-label,#selected-voice-name,.seq-toolbar,.seq-properties,.seq-warning,.samples,.control-bottom,#toast,#job-panel,.podcast-speaker-summary,#seq-studio-dialog .actions,#seq-creative-dialog .actions,.cue-speed,.cue-head,[role="status"],#download-selected-count,#download-remove-count,#download-list small'))continue;
  const display=uiLabel(original);uiOriginal.set(node,{original,display});if(node.nodeValue!==display)node.nodeValue=display;
 }
 for(const el of root.querySelectorAll('[placeholder],[title],[aria-label]')){
  if(el.closest('[data-i18n-skip],.voice-row,.seq-media-name,.seq-clip-name,.file-info,.project-open,.speaker-row button:first-of-type')||el.matches('a[download]'))continue;
  for(const attr of ['placeholder','title','aria-label']){const current=el.getAttribute(attr);if(!current)continue;const token='i18n-'+attr;let previous=uiOriginal.get(el)||{};const old=previous[token];const original=old&&current===old.display?old.original:current;
   const display=uiLabel(original);previous[token]={original,display};uiOriginal.set(el,previous);if(current!==display)el.setAttribute(attr,display);
  }
 }
}
let uiObserver,uiTranslationPending=false;
const UI_OBSERVE={childList:true,subtree:true,characterData:true,attributes:true,attributeFilter:['placeholder','title','aria-label']};
function uiTranslateSoon(){if(uiTranslationPending)return;uiTranslationPending=true;setTimeout(()=>{uiTranslationPending=false;uiObserver?.disconnect();uiTranslateDOM();uiObserver?.observe(document.body,UI_OBSERVE);},0);}
function uiSetLanguage(language){uiLanguage=Object.hasOwn(UI_LANGUAGES,language)?language:'vi';document.documentElement.lang=uiLanguage;localStorage.setItem('rv-language',uiLanguage);if(document.body){uiObserver?.disconnect();uiTranslateDOM();uiObserver?.observe(document.body,UI_OBSERVE);}}
if(typeof document!=='undefined')document.addEventListener('DOMContentLoaded',()=>{uiSetLanguage(localStorage.getItem('rv-language')||'vi');uiObserver=new MutationObserver(uiTranslateSoon);uiObserver.observe(document.body,UI_OBSERVE);});
// Native dialogs are not DOM nodes. Localize only their message, never default
// values or the text returned by the user; preserve cancellation semantics.
if(typeof window!=='undefined'){
 const nativeConfirm=window.confirm.bind(window),nativePrompt=window.prompt.bind(window);
 const message=text=>String(text).split('\n').map(line=>uiLabel(line)).join('\n');
 window.confirm=text=>nativeConfirm(message(text));
 window.prompt=(text,value)=>nativePrompt(message(text),value);
}
